   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_QUOTE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_QUOTE_HK, PREMIUM_TYPE, SUM_INSURED_SLAB
   hashdiff    : SAT_QUOTE_PREMIUM_RATE_SLAB_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTE_NO))) as HUB_QUOTE_HK
        , coalesce(nullif(trim(PREMIUM_TYPE), ''), '') as PREMIUM_TYPE
        , coalesce(nullif(trim(SI_AGE_BAND), ''), '') as SUM_INSURED_SLAB
        , PREMIUM_TYPE as PREMIUM_RATING_BASIS
        , SI_AGE_BAND as SUM_INSURED_SLAB_AMOUNT
        , RECORD_DATE as RATE_RECORD_DATE
        , SOURCE_NAME as RATE_SOURCE_NAME
        , PPP_TYPE as RATE_APPLICABILITY_STAGE
        , 'BJAZ_GRP_HLT_PREMIUM_DTLS_TYP1' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_premium_dtls_typ1') }}
    where (nullif(trim(QUOTE_NO),'')) is not null
),

resolved as (
    select
        HUB_QUOTE_HK,
        PREMIUM_TYPE,
        SUM_INSURED_SLAB,
        max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_RATING_BASIS end) as PREMIUM_RATING_BASIS,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUM_INSURED_SLAB_AMOUNT end) as SUM_INSURED_SLAB_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then RATE_RECORD_DATE end) as RATE_RECORD_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then RATE_SOURCE_NAME end) as RATE_SOURCE_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then RATE_APPLICABILITY_STAGE end) as RATE_APPLICABILITY_STAGE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_QUOTE_HK, PREMIUM_TYPE, SUM_INSURED_SLAB
),

hashed as (
    select
        *,
        case when PREMIUM_TYPE is not null or SUM_INSURED_SLAB is not null or PREMIUM_RATING_BASIS is not null or SUM_INSURED_SLAB_AMOUNT is not null or RATE_RECORD_DATE is not null or RATE_SOURCE_NAME is not null or RATE_APPLICABILITY_STAGE is not null
                     then md5(upper(coalesce(cast(PREMIUM_TYPE as varchar), '') || '|' || coalesce(cast(SUM_INSURED_SLAB as varchar), '') || '|' || coalesce(cast(PREMIUM_RATING_BASIS as varchar), '') || '|' || coalesce(cast(SUM_INSURED_SLAB_AMOUNT as varchar), '') || '|' || coalesce(cast(RATE_RECORD_DATE as varchar), '') || '|' || coalesce(cast(RATE_SOURCE_NAME as varchar), '') || '|' || coalesce(cast(RATE_APPLICABILITY_STAGE as varchar), '')))
                end as SAT_QUOTE_PREMIUM_RATE_SLAB_HASHDIFF
    from resolved
)

select * from hashed
where HUB_QUOTE_HK is not null
  and SAT_QUOTE_PREMIUM_RATE_SLAB_HASHDIFF is not null
